module edge_cnt_fix(
    input       clk,
    input       rst_n,
    input       pulse,
    output [3:0] count
);
    reg [3:0] cnt_r;
    reg       hist;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt_r <= 4'd0;
            hist  <= 1'b0;
        end else begin
            if (pulse != hist)
                cnt_r <= cnt_r + 4'd1;
            hist <= pulse;
        end
    end

    assign count = cnt_r;

endmodule

